def test_iter_ndjson_invalid_line():
    response = httpx.Response(
        200,
        content=b'{"a": 1}\n\xef\xbb\xbf{"b": 2}\n',
        headers={"Content-Type": "application/ndjson"},
    )
    iterator = response.iter_json()
    assert next(iterator) == {"a": 1}
    with pytest.raises(httpx.DecodingError):
        next(iterator)

func TestMergeIndependentAdds(t *testing.T) {
	base := mustDoc(t, `<root><a/></root>`)
	ours := mustDoc(t, `<root><a/><b/></root>`)
	theirs := mustDoc(t, `<root><a/><c/></root>`)
	merged, conflicts, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 0 {
		t.Errorf(`independent adds should not conflict: %+v`, conflicts)
	}
	if merged == nil {
		t.Fatal(`Merge3Way returned nil document`)
	}
	root := merged.Root()
	if root == nil {
		t.Fatal(`merged document has no root`)
	}
	if root.Tag != `root` {
		t.Errorf(`merged root tag = %q, want %q`, root.Tag, `root`)
	}
	if root.SelectElement(`a`) == nil {
		t.Error(`merged document lost existing element a`)
	}
	if root.SelectElement(`b`) == nil {
		t.Error(`merged document missing ours addition b`)
	}
	if root.SelectElement(`c`) == nil {
		t.Error(`merged document missing theirs addition c`)
	}
	if got := merged.Metadata[`merge.base`]; got != `root` {
		t.Errorf(`metadata merge.base = %q, want %q`, got, `root`)
	}
	if got := merged.Metadata[`merge.ours`]; got != `root` {
		t.Errorf(`metadata merge.ours = %q, want %q`, got, `root`)
	}
	if got := merged.Metadata[`merge.theirs`]; got != `root` {
		t.Errorf(`metadata merge.theirs = %q, want %q`, got, `root`)
	}
}

func TestMergeIndependentAdds(t *testing.T) {
	base := mustDoc(t, `<root><a/></root>`)
	ours := mustDoc(t, `<root><a/><b/></root>`)
	theirs := mustDoc(t, `<root><a/><c/></root>`)
	merged, conflicts, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 0 {
		t.Errorf("independent adds should not conflict: %+v", conflicts)
	}
	if merged == nil {
		t.Fatal("Merge3Way returned nil document without error")
	}
	root := merged.Root()
	if root == nil || root.Tag != "root" {
		t.Fatalf("merged root wrong: %v", root)
	}
	kids := root.ChildElements()
	if n := len(kids); n != 3 {
		t.Fatalf("merged should retain all three children, got %d: %s", n, docStr(t, merged))
	}
	seen := map[string]int{}
	for _, k := range kids {
		seen[k.Tag]++
	}
	if seen["a"] != 1 || seen["b"] != 1 || seen["c"] != 1 {
		t.Errorf("merged document should contain a, b and c: %v (%s)", seen, docStr(t, merged))
	}
	if merged.Metadata == nil {
		t.Fatal("merged metadata is nil")
	}
	if merged.Metadata["merge.base"] != "root" || merged.Metadata["merge.ours"] != "root" || merged.Metadata["merge.theirs"] != "root" {
		t.Errorf("merge metadata wrong: %v", merged.Metadata)
	}
}

func TestDurabilityNotify(t *testing.T) {
	d := openDurabilityTestDB(t, nil)

	// Already-durable seqnum returns nil immediately.
	select {
	case err := <-d.DurabilityNotify(0):
		require.NoError(t, err)
	case <-time.After(5 * time.Second):
		t.Fatal("timed out")
	}

	// A non-sync commit must not make its sequence number durable: a
	// notification for it must not fire before any WAL sync covers it.
	nb := d.NewBatch()
	require.NoError(t, nb.Set([]byte("nosync"), []byte("1"), nil))
	require.NoError(t, d.Apply(nb, NoSync))
	nosyncSeq := nb.SeqNum()
	require.NoError(t, nb.Close())
	ch := d.DurabilityNotify(nosyncSeq)
	select {
	case err := <-ch:
		t.Fatalf("notification fired before commit was durable: %v", err)
	case <-time.After(100 * time.Millisecond):
	}

	// A sync commit makes its sequence number range durable, and the WAL sync
	// also covers the earlier non-sync commit.
	b := d.NewBatch()
	require.NoError(t, b.Set([]byte("a"), []byte("1"), nil))
	require.NoError(t, b.Set([]byte("b"), []byte("2"), nil))
	require.NoError(t, d.Apply(b, Sync))
	seqNum := b.SeqNum()
	require.NoError(t, b.Close())

	ch2 := d.DurabilityNotify(seqNum)
	ch3 := d.DurabilityNotify(seqNum + 1)
	select {
	case err := <-ch2:
		require.NoError(t, err)
	case <-time.After(5 * time.Second):
		t.Fatal("timed out waiting for durability notify")
	}
	select {
	case err := <-ch3:
		require.NoError(t, err)
	case <-time.After(5 * time.Second):
		t.Fatal("timed out waiting for durability notify")
	}
	select {
	case err := <-ch:
		require.NoError(t, err)
	case <-time.After(5 * time.Second):
		t.Fatal("timed out waiting for durability notify of earlier non-sync commit")
	}

	// An outstanding notification that never becomes durable receives a non-nil
	// error when the DB is closed.
	future := d.DurabilityNotify(1 << 40)
	require.NoError(t, d.Close())
	select {
	case err := <-future:
		require.Error(t, err)
		require.True(t, errors.Is(err, ErrClosed))
	case <-time.After(5 * time.Second):
		t.Fatal("notify not unblocked on close")
	}
}

it('adds and removes traits', () => {
        const world = createWorld();

        // add then remove in the same buffer: final state must be removed
        const e1 = world.spawn();
        world.deferred.add(e1, A({ value: 5 }));
        world.deferred.remove(e1, A);
        expect(e1.has(A)).toBe(false);
        expect(e1.get(A)).toBeUndefined();
        world.deferred.flush();
        expect(e1.has(A)).toBe(false);
        expect(world.query(A)).not.toContain(e1);

        // remove then add in the same buffer: final state must be added with later value
        const e2 = world.spawn();
        world.deferred.remove(e2, A); // no-op
        world.deferred.add(e2, A({ value: 7 }));
        expect(e2.has(A)).toBe(true);
        expect(e2.get(A)!.value).toBe(7);
        world.deferred.flush();
        expect(world.query(A)).toContain(e2);
        expect(e2.get(A)!.value).toBe(7);

        // later add for the same trait replaces earlier one
        const e3 = world.spawn();
        world.deferred.add(e3, A({ value: 8 }));
        world.deferred.add(e3, A({ value: 9 }));
        expect(e3.get(A)!.value).toBe(9);
        world.deferred.flush();
        expect(e3.get(A)!.value).toBe(9);

        // add then destroy: add command is skipped because entity is destroyed
        const e4 = world.spawn();
        world.deferred.add(e4, A({ value: 10 }));
        world.deferred.destroy(e4);
        expect(e4.isAlive()).toBe(false);
        expect(e4.has(A)).toBe(false);
        world.deferred.flush();
        expect(world.has(e4)).toBe(false);
        expect(world.query(A)).not.toContain(e4);

        // destroy then add: add command is skipped
        const e5 = world.spawn();
        world.deferred.destroy(e5);
        world.deferred.add(e5, A({ value: 11 }));
        expect(e5.isAlive()).toBe(false);
        world.deferred.flush();
        expect(world.has(e5)).toBe(false);
        expect(world.query(A)).not.toContain(e5);

        // multiple flushes are idempotent
        const e6 = world.spawn();
        world.deferred.add(e6, A({ value: 12 }));
        world.deferred.flush();
        world.deferred.flush();
        expect(e6.get(A)!.value).toBe(12);
        expect(world.query(A).filter((e) => e === e6)).toHaveLength(1);
    });

it('spawns entities on flush', () => {
        const world = createWorld();
        const entity = world.deferred.spawn(A({ value: 1 }));

        expect(entity.has(A)).toBe(true);
        expect(entity.get(A)!.value).toBe(1);
        expect(world.has(entity)).toBe(true);
        expect(world.entities).not.toContain(entity);

        // deferred add and remove on the spawned entity before flush
        world.deferred.add(entity, B({ value: 2 }));
        world.deferred.remove(entity, A);

        expect(entity.has(A)).toBe(false);
        expect(entity.get(A)).toBeUndefined();
        expect(entity.has(B)).toBe(true);
        expect(entity.get(B)!.value).toBe(2);

        world.deferred.flush();

        expect(world.entities).toContain(entity);
        expect(entity.has(A)).toBe(false);
        expect(entity.has(B)).toBe(true);
        expect(entity.get(B)!.value).toBe(2);
        expect(world.query(B)).toContain(entity);
        expect(world.query(A)).not.toContain(entity);

        // spawn-destroy in the same buffer nullifies both
        const nullified = world.deferred.spawn(A({ value: 3 }));
        world.deferred.destroy(nullified);
        expect(nullified.isAlive()).toBe(false);
        world.deferred.flush();
        expect(world.has(nullified)).toBe(false);
        expect(world.entities).not.toContain(nullified);
        expect(world.query(A)).not.toContain(nullified);

        // commands on a spawned-and-destroyed entity are silently skipped
        const nullified2 = world.deferred.spawn(A({ value: 4 }));
        world.deferred.destroy(nullified2);
        world.deferred.add(nullified2, B({ value: 5 }));
        world.deferred.flush();
        expect(world.has(nullified2)).toBe(false);
        expect(world.query(B)).not.toContain(nullified2);

        // addExclusive replaces previous pairs, later add appends
        const subject = world.spawn();
        const targetA = world.spawn();
        const targetB = world.spawn();
        const targetC = world.spawn();
        world.deferred.add(subject, Likes(targetA));
        world.deferred.add(subject, Likes(targetB));
        world.deferred.addExclusive(subject, Likes(targetC));
        expect(subject.has(Likes(targetA))).toBe(false);
        expect(subject.has(Likes(targetB))).toBe(false);
        expect(subject.has(Likes(targetC))).toBe(true);
        world.deferred.flush();
        expect(subject.targetsFor(Likes)).toEqual([targetC]);

        const subject2 = world.spawn();
        const targetD = world.spawn();
        const targetE = world.spawn();
        world.deferred.addExclusive(subject2, Likes(targetD));
        world.deferred.add(subject2, Likes(targetE));
        expect(subject2.has(Likes(targetD))).toBe(true);
        expect(subject2.has(Likes(targetE))).toBe(true);
        world.deferred.flush();
        expect(subject2.targetsFor(Likes)).toHaveLength(2);
        expect(subject2.targetsFor(Likes)).toContain(targetD);
        expect(subject2.targetsFor(Likes)).toContain(targetE);

        world.deferred.addExclusive(subject2, Likes, '*');
        expect(subject2.has(Likes(targetD))).toBe(false);
        expect(subject2.has(Likes(targetE))).toBe(false);
        world.deferred.flush();
        expect(subject2.targetsFor(Likes)).toEqual([]);
    });

it('spawns entities on flush', () => {
        const world = createWorld();
        const entity = world.deferred.spawn(A({ value: 1 }));
        const bare = world.deferred.spawn(A);

        expect(entity.has(A)).toBe(true);
        expect(entity.get(A)!.value).toBe(1);
        expect(bare.has(A)).toBe(true);
        expect(bare.get(A)!.value).toBe(0);
        expect(entity.isAlive()).toBe(true);
        expect(bare.isAlive()).toBe(true);
        expect(world.has(entity)).toBe(true);
        expect(world.has(bare)).toBe(true);
        expect(world.entities).not.toContain(entity);
        expect(world.entities).not.toContain(bare);
        expect(world.query(A)).not.toContain(entity);
        expect(world.query(A)).not.toContain(bare);

        world.deferred.flush();

        expect(world.entities).toContain(entity);
        expect(world.entities).toContain(bare);
        expect(entity.get(A)!.value).toBe(1);
        expect(bare.get(A)!.value).toBe(0);
        expect(world.query(A)).toContain(entity);
        expect(world.query(A)).toContain(bare);
    });

it('adds and removes traits', () => {
        const world = createWorld();
        const entity = world.spawn();

        world.deferred.add(entity, A({ value: 5 }));
        expect(entity.has(A)).toBe(true);
        expect(entity.get(A)!.value).toBe(5);
        expect(world.query(A)).not.toContain(entity);

        world.deferred.flush();
        expect(entity.get(A)!.value).toBe(5);
        expect(world.query(A)).toContain(entity);

        world.deferred.remove(entity, A);
        expect(entity.has(A)).toBe(false);
        world.deferred.flush();
        expect(world.query(A)).not.toContain(entity);

        world.deferred.add(entity, A);
        expect(entity.has(A)).toBe(true);
        expect(entity.get(A)!.value).toBe(0);
        world.deferred.flush();
        expect(entity.get(A)!.value).toBe(0);
        expect(world.query(A)).toContain(entity);

        world.deferred.add(entity, A({ value: 7 }));
        world.deferred.add(entity, A({ value: 9 }));
        expect(entity.get(A)!.value).toBe(9);
        world.deferred.flush();
        expect(entity.get(A)!.value).toBe(9);
    });
